import React, {Component} from 'react';
import PropTypes from 'prop-types';

import LoaderInline from '../loader-inline/loader-inline';

import UserCardTooltip, {UserCardTooltipAttrs} from './tooltip';
import styles from './user-card.css';
import {UserCardUser} from './card';

export interface SmartUserCardTooltipProps extends UserCardTooltipAttrs {
  userDataSource: () => Promise<UserCardUser | null | undefined> | UserCardUser | null | undefined
}
export default class SmartUserCardTooltip extends Component<SmartUserCardTooltipProps> {
  static propTypes = {
    children: PropTypes.node,
    userDataSource: PropTypes.func
  };

  state = {
    user: null,
    loading: false
  };

  loadUser = async () => {
    if (this.state.user) {
      return;
    }

    try {
      this.setState({loading: true});
      const user = await this.props.userDataSource();
      this.setState({user});
    } catch (e) {
      // Skip it
    } finally {
      this.setState({loading: false});
    }
  };

  renderNoUser = () => (
    this.state.loading
      ? (
        <div className={styles.userCardSpaced}>
          <LoaderInline/>
        </div>
      )
      : ''
  );

  render() {
    const {user} = this.state;
    const {children, userDataSource, ...restProps} = this.props;

    const dropdownProps = {
      onMouseEnter: this.loadUser,
      ...UserCardTooltip.defaultProps.dropdownProps
    };

    return (
      <UserCardTooltip
        user={user}
        renderNoUser={this.renderNoUser}
        dropdownProps={dropdownProps}
        {...restProps}
      >
        {children}
      </UserCardTooltip>
    );
  }
}

import React, {Component, ReactElement, ReactNode} from 'react';
import classNames from 'classnames';
import PropTypes from 'prop-types';

import Dropdown, {DropdownAttrs} from '../dropdown/dropdown';
import Popup from '../popup/popup';

import UserCard, {UserCardAttrs, UserCardUser} from './card';
import styles from './user-card.css';

const DEFAULT_TIMEOUT = 300;

export interface UserCardTooltipProps extends Omit<UserCardAttrs, 'user'> {
  user?: UserCardUser | null | undefined
  children: ReactElement | readonly ReactElement[] | string
  dropdownProps: Partial<DropdownAttrs>
  renderUserCard: (props: UserCardTooltipProps) => ReactNode
  renderNoUser: () => ReactNode
}
export default class UserCardTooltip extends Component<UserCardTooltipProps> {
  static propTypes = {
    className: PropTypes.string,
    children: PropTypes.node,
    dropdownProps: PropTypes.object,
    user: PropTypes.object,
    renderUserCard: PropTypes.func,
    renderNoUser: PropTypes.func
  };

  static defaultProps = {
    renderUserCard: (props: UserCardTooltipProps) => {
      const {className,
        children, renderUserCard, renderNoUser, dropdownProps, user, ...restProps} = props;

      return user && (
        <UserCard
          user={user}
          {...restProps}
          className={classNames(styles.userCardSpaced, className)}
        />
      );
    },
    renderNoUser: () => '',
    dropdownProps: {
      hoverShowTimeOut: DEFAULT_TIMEOUT,
      hoverHideTimeOut: DEFAULT_TIMEOUT
    }
  };

  render() {
    const {children, user, renderUserCard, renderNoUser, dropdownProps} = this.props;

    return (
      <Dropdown
        anchor={children}
        hoverMode
        clickMode={false}
        {...dropdownProps}
      >
        <Popup attached={false}>
          {user ? renderUserCard(this.props) : renderNoUser()}
        </Popup>
      </Dropdown>
    );
  }
}
export type UserCardTooltipAttrs =
  JSX.LibraryManagedAttributes<typeof UserCardTooltip, UserCardTooltipProps>

