inline.storyName = 'inline';

export const smartTooltip = () => {
  const user = {
    login: 'testuser',
    name: 'Test User',
    email: 'testuser@mail.com',
    avatarUrl: avatarDataUri,
    href: `${hubConfig.serverUri}/users/0`,
    banned: true,
    online: false,
    banReason: 'Bad guy: is accused of stealing potatoes!'
  };

  function loadUser() {
